    resolveRendition: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                trackId: components["parameters"]["TrackId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "purpose": "stream",
                 *       "quality": "original",
                 *       "accept": [
                 *         {
                 *           "container": "flac",
                 *           "codec": "flac"
                 *         },
                 *         {
                 *           "container": "mp3",
                 *           "codec": "mp3"
                 *         },
                 *         {
                 *           "container": "m4a",
                 *           "codec": "aac"
                 *         },
                 *         {
                 *           "container": "ogg",
                 *           "codec": "opus"
                 *         },
                 *         {
                 *           "container": "ogg",
                 *           "codec": "vorbis"
                 *         }
                 *       ]
                 *     }
                 */
                "application/json": components["schemas"]["RenditionRequest"];
            };
        };
        responses: {
            /** @description 바로 사용 가능 */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "id": "rnd_01JB2R7G9J1L3N5Q7S9U1W3Y5A",
                     *       "track_id": "trk_01JB2P3C5E7G9J1L3N5Q7S9U1W",
                     *       "media_version": "k7q2m9x4b1c8d5f0",
                     *       "profile": "original",
                     *       "state": "ready",
                     *       "mime": "audio/flac",
                     *       "container": "flac",
                     *       "codec": "flac",
                     *       "size_bytes": 24561892,
                     *       "duration_ms": 215340,
                     *       "sha256": "9f2c1e0d6b7a48c3a5d4e1f09b8c7d6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c",
                     *       "etag": "\"k7q2m9x4b1c8d5f0-original\"",
                     *       "seekable": true,
                     *       "media_url": "/v1/media/rnd_01JB2R7G9J1L3N5Q7S9U1W3Y5A?mt=eyJ2IjoxLC...redacted",
                     *       "ticket_expires_at": "2026-10-02T15:00:00Z"
                     *     }
                     */
                    "application/json": components["schemas"]["Rendition"];
                };
            };
            /** @description 변환 준비 중 */
            202: {
                headers: {
                    /** @description 다음 폴링까지 권장 초 */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Rendition"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            /** @description `not_found`(곡 없음/권한 없음) 또는 `media_missing`(곡은 있으나 원본 파일이 사라짐) */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description `no_playable_format` — 앱이 받을 수 있는 형식이 없고 서버 변환도 꺼져 있음 */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            426: components["responses"]["ClientTooOld"];
            /** @description `transcode_queue_full` — 변환 대기열 한도 초과. `Retry-After` 후 재시도. */
            429: {
                headers: {
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            503: components["responses"]["Unavailable"];
        };
    };
